// All lesson content is kept here; edit teacher links/media in config.js.
const config = window.WEBQUEST_CONFIG || {};
const signup=config.signup || 'https://docs.google.com/forms/d/e/1FAIpQLSf0Vvk0uepud-2IeNhvMDAR87B2HvaDJvrSlNhsRb2LvmcBiA/viewform';
const submit=config.submission || 'https://docs.google.com/forms/d/e/1FAIpQLSeVar6It8CpfL3DdyOYlfQKV8uLOdVDO_dVhzAsUyVgo8VfIg/viewform';
const menu=[['gioi-thieu','Giới thiệu'],['nhiem-vu','Nhiệm vụ'],['tien-trinh','Tiến trình'],['hoc-lieu','Học liệu'],['danh-gia','Đánh giá – Nộp bài'],['ket-luan','Kết luận']];
const clubIcons=['💻','🔬','📚','🌍','📣','🎵','🎨','🏀','♟️','🌱'];
const clubs=['Tin học','STEM','Đọc sách','Tiếng Anh','Truyền thông','Âm nhạc','Mĩ thuật','Thể thao','Cờ vua','Môi trường'];
const head=(label,title,text)=>`<div class="eyebrow">${label}</div><h1>${title}</h1><p class="lead">${text}</p>`;
const card=(title,text,cls='')=>`<article class="card ${cls}"><h3>${title}</h3>${text}</article>`;
const pages={
'gioi-thieu':()=>`<section class="hero"><div>${head('WebQuest · Tin học 12 · ICT','Kết nối<br>câu lạc bộ','Làm thế nào để một học sinh tìm hiểu và đăng ký tham gia câu lạc bộ qua một website dễ sử dụng?')}<p>Nhóm em đóng vai đội thiết kế website cho một câu lạc bộ của trường. Hãy tìm hiểu nhu cầu người xem, xây dựng website, cho nhóm bạn dùng thử rồi hoàn thiện trước khi giới thiệu sản phẩm.</p><div class="actions"><a class="button" href="#nhiem-vu">Xem nhiệm vụ</a><a class="button alt" href="#tien-trinh">Đăng ký nhóm</a></div></div><aside class="hero-art"><div class="art-badge">Cùng thiết kế · Cùng khám phá</div>${config.heroImage ? `<img class="hero-image" src="${escape(config.heroImage)}" alt="${escape(config.heroAlt || '')}" fetchpriority="high" width="1200" height="900">` : ''}<div class="art-caption"><span class="caption-symbol" aria-hidden="true">✦</span><span>Một ý tưởng của nhóm.<br><strong>Một website cho cộng đồng.</strong></span></div></aside></section><div class="strip"><div><b>4 tiết</b>180 phút trên lớp</div><div><b>5 nhóm</b>6–8 học sinh / nhóm</div><div><b>3 trang</b>Trang chủ · Hoạt động · Tham gia</div><div><b>1 báo cáo</b>Lưu quá trình thực hiện</div></div><section class="roadmap-section"><div class="roadmap-label"><span>Lộ trình của nhóm em</span><span class="pill">4 tiết</span></div><a class="roadmap-link" href="#tien-trinh"><span class="roadmap-index">01</span><span><strong>Hiểu nhiệm vụ & thiết kế</strong><small>Chọn CLB · Phân công · Phác thảo</small></span></a><a class="roadmap-link" href="#tien-trinh"><span class="roadmap-index">02</span><span><strong>Tạo website phiên bản đầu</strong><small>Ba trang · Menu · Biểu mẫu</small></span></a><a class="roadmap-link" href="#tien-trinh"><span class="roadmap-index">03</span><span><strong>Dùng thử & hoàn thiện</strong><small>Nhận góp ý · Chỉnh sửa · Nộp bài</small></span></a><a class="roadmap-link" href="#tien-trinh"><span class="roadmap-index">04</span><span><strong>Giới thiệu sản phẩm</strong><small>7 phút báo cáo · 2 phút trao đổi</small></span></a></section><div class="grid">${card('Người xem','<p>Học sinh đang tìm một câu lạc bộ phù hợp với sở thích.</p>','tint')}${card('Sản phẩm cuối','<p>Website CLB có menu, bài viết, hình ảnh và biểu mẫu tham gia.</p>')}${card('Giá trị sử dụng','<p>Giúp người xem hiểu CLB và thực hiện được bước đăng ký.</p>','yellow')}</div><h2>Em sẽ học được gì?</h2><div class="two">${card('Kiến thức','<ul><li>Sử dụng được một số chức năng cơ bản của phần mềm tạo trang web.</li><li>Tạo được một trang web tĩnh đơn giản gồm menu liên kết các trang, tiêu đề, bài viết, ảnh đại diện và mẫu biểu.</li></ul>')}${card('Năng lực và phẩm chất','<ul><li>Tạo được trang web đơn giản. (1)</li><li>Khai thác dịch vụ tra cứu, trao đổi thông tin và nguồn học liệu mở để cập nhật kiến thức, hỗ trợ học tập, tự học. (2)</li><li>Sử dụng phần mềm hỗ trợ học tập. (3)</li><li>Phân tích công việc cần thực hiện để hoàn thành nhiệm vụ nhóm. (4)</li><li>Tích cực tìm tòi và sáng tạo trong học tập. (5)</li></ul>')}</div>`,
'nhiem-vu':()=>`${head('02 · Nhiệm vụ','Thiết kế website cho một CLB','Website phải giúp người xem trả lời: CLB làm gì, có phù hợp với mình không và tham gia bằng cách nào?')}<h2>Chọn một câu lạc bộ</h2><div class="grid club-grid">${clubs.map((c,i)=>card(`<span class="club-icon" aria-hidden="true">${clubIcons[i]}</span><span>${c}</span>`,'<p>Chọn đề tài trong form đăng ký. Giáo viên xác nhận trước khi nhóm bắt đầu.</p>')).join('')}</div><div class="notice">Trong cùng một lớp, các nhóm cần chọn đề tài khác nhau sau khi giáo viên xác nhận. Có thể dùng CLB thực tế với thông tin đã kiểm chứng hoặc mô hình CLB giả định được ghi rõ.</div><h2>Cấu trúc website cần nộp</h2><div class="grid">${card('01 · Trang chủ','<ul><li>Tên CLB, lời giới thiệu và đối tượng phù hợp.</li><li>Ảnh đại diện có quyền sử dụng và nguồn.</li><li>Nút dẫn đến Hoạt động và Tham gia.</li></ul>')}${card('02 · Hoạt động','<ul><li>Giới thiệu các hoạt động tiêu biểu: tên, nội dung và cách tham gia.</li><li>Thông tin thời gian, địa điểm nếu có căn cứ; thông tin giả định phải gắn nhãn.</li><li>Ảnh minh họa và chú thích liên quan.</li></ul>')}${card('03 · Tham gia','<ul><li>Đối tượng, điều kiện và hướng dẫn đăng ký.</li><li>Nhúng Google Form của CLB, có liên kết mở riêng.</li><li>Chỉ hỏi thông tin cần thiết; dùng dữ liệu giả khi thử.</li></ul>')}</div><h2>Yêu cầu trình bày</h2><div class="two">${card('Bố cục','<p>Menu xuất hiện thống nhất trên ba trang. Mỗi trang có tiêu đề rõ, nội dung chia thành các khối theo thứ tự đọc. Ảnh không che chữ; kiểm tra trên máy tính và điện thoại.</p>')}${card('Màu sắc và chữ','<p>Chọn màu chủ đạo và màu nhấn nhất quán. Chữ dễ đọc, phân biệt rõ với nền. Tiêu đề cùng cấp dùng cùng kiểu chữ; không dùng màu làm dấu hiệu duy nhất.</p>')}</div><h2>Gói nộp cuối cùng</h2><ol><li><b>Link website đã xuất bản</b>, có quyền xem phù hợp và hoạt động đủ ba trang.</li><li><b>Link một file báo cáo DOCX</b>: thành viên, phân công, ý tưởng, nguồn, quá trình dùng thử và chỉnh sửa. <a href="MauBaoCao.docx" download>Tải mẫu báo cáo</a>.</li></ol><p>Không yêu cầu thêm một bài trình chiếu. Nhóm báo cáo trực tiếp bằng website.</p><a class="button" href="#tien-trinh">Xem lộ trình thực hiện</a>`,
 'tien-trinh':()=>`${head('03 · Tiến trình','Từ ý tưởng đến website dùng được','Bốn hoạt động trải dài toàn dự án. Không khởi động lại ở mỗi tiết.')}<div class="table-wrap"><table><tr><th>Tiết</th><th>Hoạt động</th><th>Thời lượng</th><th>Kết quả</th></tr><tr><td>1</td><td>Khởi động; hình thành kiến thức 2.1</td><td>10 + 35 phút</td><td>Đề tài được xác nhận, phân công và bản thiết kế ba trang.</td></tr><tr><td>2</td><td>Hình thành kiến thức 2.2; luyện tập</td><td>15 + 30 phút</td><td>Website phiên bản đầu, menu, nội dung và form.</td></tr><tr><td>3</td><td>Vận dụng: dùng thử, chỉnh sửa, nộp bài</td><td>45 phút</td><td>Website hoàn thiện và báo cáo DOCX.</td></tr><tr><td>4</td><td>Vận dụng: báo cáo và trao đổi</td><td>45 phút</td><td>Mỗi nhóm 7 phút báo cáo + 2 phút hỏi đáp.</td></tr></table></div><section class="step"><h2>Tiết 1 · Hiểu nhiệm vụ và thiết kế</h2><p><b>10 phút:</b> Xem website mẫu, xác định thông tin người muốn tham gia CLB cần biết. Chọn CLB, đăng ký và chờ giáo viên xác nhận.</p><p><b>35 phút:</b> Khai thác hướng dẫn tạo trang, menu, văn bản và ảnh. Nhóm phác thảo ba trang, chọn nguồn và phân tích các công việc cần làm.</p><p><b>Giáo viên:</b> Giới thiệu vấn đề, cung cấp nguồn, xác nhận đề tài và hỗ trợ thao tác. <b>Học sinh:</b> Thảo luận nhu cầu người xem, lập thiết kế, phân công và bắt đầu tạo trang.</p><details><summary>Phân công cho 6–8 thành viên</summary><p>Với 6 học sinh: ba cặp cùng phụ trách ba trang; mỗi người trực tiếp tạo hoặc chỉnh sửa một phần và kiểm tra phần của bạn. Nếu có thành viên thứ 7 hoặc 8, phân thêm việc tạo form, xử lý ảnh, thử liên kết; vẫn phải có phần trực tiếp thao tác trên website.</p><p>Báo cáo ghi rõ: công việc, kết quả cần có, người thực hiện và thời điểm hoặc công việc phụ thuộc. Nhóm cân đối lại khi một người có quá nhiều việc.</p></details></section><section class="step"><h2>Tiết 2 · Tạo phiên bản đầu</h2><p><b>15 phút:</b> Thử nhúng form, chèn liên kết và xem trước. Giáo viên hướng dẫn ngắn bằng sản phẩm mẫu, học sinh thực hiện lại trên website nhóm.</p><p><b>30 phút:</b> Các thành viên tạo nội dung theo phân công, hoàn thiện menu và ba trang. Ghi nguồn ảnh, thông tin đã sử dụng vào báo cáo chung.</p><p><b>Kết quả:</b> Bản đầu đủ cấu trúc để người khác dùng thử. Giáo viên quan sát thao tác riêng của từng học sinh.</p></section><section class="step"><h2>Tiết 3 · Dùng thử và hoàn thiện</h2><p><b>10 phút:</b> Đổi website với một nhóm khác. Người thử thực hiện ba việc: tìm một hoạt động, tìm điều kiện tham gia, mở và thử gửi form bằng dữ liệu giả.</p><p><b>5 phút:</b> Ghi rõ chỗ khó tìm, liên kết không chạy hoặc bước chưa hiểu; góp ý cụ thể.</p><p><b>20 phút:</b> Nhóm chọn vấn đề cần sửa, sửa website và thử lại. Báo cáo ghi góp ý, cách xử lý và minh chứng trước–sau.</p><p><b>10 phút:</b> Xuất bản, kiểm tra quyền xem, hoàn thiện DOCX và nộp hai liên kết. Chuẩn bị thứ tự báo cáo để tiết 4 không mất thời gian chuyển nhóm.</p><p>Nếu cần hoàn thiện ngoài lớp, nhóm thống nhất trước khoảng 45–60 phút cho mỗi học sinh; không giao toàn bộ việc còn lại cho một thành viên.</p></section><section class="step"><h2>Tiết 4 · Giới thiệu sản phẩm</h2><p>5 nhóm × 9 phút = 45 phút. Mỗi nhóm <b>7 phút</b> giới thiệu người xem mục tiêu, ba trang, cách đăng ký và một chỉnh sửa sau dùng thử; <b>2 phút</b> trả lời câu hỏi. Phân lượt trình bày phù hợp để các thành viên có minh chứng tham gia.</p><p>Giáo viên chấm theo rubric và phản hồi dựa trên minh chứng quá trình, sản phẩm và thao tác cá nhân.</p></section><h2>Đăng ký nhóm và đề tài</h2><p>Chọn đúng năm học, lớp và nhóm. Không dùng form này để đăng ký tham gia một CLB.</p><a class="button alt" href="${signup}" target="_blank" rel="noopener">Mở form riêng</a><iframe title="Form đăng ký nhóm và đề tài" src="${signup}?embedded=true" loading="lazy"></iframe>`,
'hoc-lieu':()=>`${head('04 · Nguồn tư liệu','Học liệu để bắt tay vào làm','Dùng những tài liệu dưới đây trước khi tìm thêm nguồn. Kiểm tra và ghi nguồn thông tin, ảnh của CLB vào báo cáo.')}<div class="grid">${card('Website CLB mẫu','<p>Ví dụ giả định của CLB Đọc sách: ba trang, hoạt động và biểu mẫu minh họa.</p><a class="button" href="mau.html" target="_blank">Xem sản phẩm mẫu</a>','tint')}${card('Mẫu báo cáo nhóm','<p>Một file DOCX dùng xuyên suốt để lưu phân công, nguồn, quá trình và góp ý.</p><a class="button alt" href="MauBaoCao.docx" download>Tải mẫu DOCX</a>')}${card('Hướng dẫn từng bước','<p>Làm theo các mục thao tác bên dưới, sau đó dùng chức năng xem trước để kiểm tra.</p>','yellow')}</div><h2>Hướng dẫn thực hành</h2><details open><summary>1. Tạo website và ba trang</summary><ol><li>Mở Google Sites, tạo trang web mới; đặt tên theo CLB nhóm chọn.</li><li>Trong thẻ Trang, tạo Trang chủ, Hoạt động, Tham gia.</li><li>Chọn vị trí menu thống nhất; xem trước và thử chuyển cả ba trang.</li></ol><a href="https://support.google.com/sites/answer/98081?hl=vi" target="_blank" rel="noopener">Hướng dẫn chính thức: tạo trang web</a></details><details><summary>2. Chèn và sắp xếp nội dung</summary><ol><li>Trong Chèn, thêm hộp văn bản và hình ảnh phù hợp với từng trang.</li><li>Chia nội dung thành các phần có tiêu đề; đặt ảnh gần nội dung liên quan.</li><li>Chọn giao diện và màu; kiểm tra xem trước trên màn hình nhỏ.</li></ol><a href="https://support.google.com/sites/answer/90569?hl=vi" target="_blank" rel="noopener">Hướng dẫn chính thức: thêm nội dung</a></details><details><summary>3. Tạo và nhúng form của CLB</summary><ol><li>Tạo Google Form hỏi tên dùng thử, lớp, lựa chọn hoạt động và xác nhận muốn tham gia. Không hỏi dữ liệu nhạy cảm.</li><li>Trong Google Sites, chọn Chèn → Biểu mẫu, chọn form nhóm tạo.</li><li>Thêm nút mở form riêng; thử bằng dữ liệu giả và kiểm tra phản hồi.</li></ol><p>Đây là form trên sản phẩm CLB, khác form đăng ký đề tài và form nộp bài của giáo viên.</p><a href="https://support.google.com/docs/answer/6281888?hl=vi" target="_blank" rel="noopener">Hướng dẫn chính thức: Google Forms</a></details><details><summary>4. Xuất bản và kiểm tra quyền xem</summary><ol><li>Chọn Xuất bản, đặt địa chỉ và quyền xem theo hướng dẫn của giáo viên.</li><li>Sao chép liên kết đã xuất bản; mở từ tài khoản hoặc cửa sổ khác có quyền phù hợp.</li><li>Thử menu, nút và form; kiểm tra link báo cáo DOCX trước khi nộp.</li></ol><a href="https://support.google.com/sites/answer/6372880?hl=vi" target="_blank" rel="noopener">Hướng dẫn chính thức: xuất bản và chia sẻ</a></details><h2>Ảnh và video của lớp</h2><div class="two"><div class="image-slot">${config.classImage ? `<img src="${escape(config.classImage)}" alt="${escape(config.classImageAlt || '')}" loading="lazy" onerror="this.hidden=true">` : ''}<b>Minh họa CLB Đọc sách</b><p>Ảnh được tạo bằng AI cho sản phẩm mẫu giả định. Khi làm CLB thật, nhóm dùng ảnh có quyền sử dụng và ghi nguồn.</p></div><div class="image-slot"><b>Video hướng dẫn của giáo viên</b>${config.videoEmbed ? `<iframe class="video-frame" title="Video hướng dẫn thực hành" src="${escape(config.videoEmbed)}" loading="lazy" allowfullscreen></iframe>` : '<p>Chưa có video riêng được cung cấp. Các bước thực hành và tài liệu chính thức phía trên có thể sử dụng ngay.</p>'}${config.videoLink ? `<a href="${escape(config.videoLink)}" target="_blank" rel="noopener">Mở video riêng</a>` : ''}</div></div><h2>Căn cứ và nguồn tham khảo</h2><ul><li>Bộ GDĐT, Chương trình GDPT môn Tin học 2018: lớp 12, Chủ đề E, định hướng ICT, trang 53 bản chương trình đã cung cấp.</li><li>Bộ GDĐT, Công văn 5512/BGDĐT-GDTrH, Phụ lục IV: cấu trúc kế hoạch bài dạy.</li><li><a href="https://www.pblworks.org/gold-standard/pbl-project-design" target="_blank" rel="noopener">PBLWorks – các yếu tố thiết kế dạy học dự án</a>.</li><li>Google Sites và Google Forms Help: các hướng dẫn thao tác được liên kết ở trên.</li></ul>`,
'danh-gia':()=>`${head('05 · Đánh giá – Nộp bài','Biết tiêu chí trước khi nộp','Điểm sản phẩm website chiếm 60%; điểm quá trình và kĩ năng cá nhân chiếm 40%. Xem từng tiêu chí trước khi hoàn thiện website và báo cáo.')}<div id="rubrics"><p>Đang tải bảng tiêu chí…</p></div><h2>Kiểm tra trước khi nộp</h2><ul class="checklist"><li>Website đã xuất bản; ba trang và menu hoạt động.</li><li>Nội dung CLB có căn cứ hoặc đã ghi rõ là giả định.</li><li>Form CLB mở được; dữ liệu thử không phải thông tin cá nhân thật.</li><li>Báo cáo DOCX có thành viên, phân công, nguồn và chỉnh sửa sau dùng thử.</li><li>Hai liên kết có quyền xem phù hợp; đã thử mở trước khi gửi.</li></ul><h2>Nộp sản phẩm</h2><p>Chọn đúng năm học, lớp, nhóm; gửi link website và link báo cáo DOCX. Không gửi link chỉnh sửa form.</p><a class="button alt" href="${submit}" target="_blank" rel="noopener">Mở form nộp bài riêng</a><iframe title="Form nộp website và báo cáo" src="${submit}?embedded=true" loading="lazy"></iframe>`,
'ket-luan':()=>`${head('06 · Kết luận','Một website có người dùng','Sản phẩm hoàn thành khi người xem hiểu câu lạc bộ và thực hiện được bước tham gia.')}<div class="grid">${card('Nhìn lại','<p>Điều gì trên website giúp người xem tìm thông tin nhanh hơn? Nhóm đã thay đổi gì sau khi quan sát người dùng thử?</p>')}${card('Tự đánh giá','<p>Em trực tiếp thực hiện thao tác nào? Em dùng học liệu nào để giải quyết việc chưa biết và có thể thực hiện lại thao tác đó không?</p>','tint')}${card('Phát triển tiếp','<p>Nếu CLB dùng website thực tế, cần xác nhận thông tin với người phụ trách và thống nhất cách cập nhật hoạt động.</p>','yellow')}</div><h2>Sử dụng cho nhiều lớp, nhiều năm</h2><p>Form đăng ký và nộp bài dùng trường năm học, lớp, nhóm để phân biệt dữ liệu. Mỗi đợt triển khai, giáo viên cập nhật danh sách lớp, thời hạn và học liệu; giữ nguyên lộ trình và cập nhật nguồn khi cần.</p><p>Minh chứng được tổ chức theo <b>Năm học / Lớp / Nhóm / Sản phẩm – Báo cáo – Dùng thử</b>. Không công bố thông tin cá nhân hoặc quyền chỉnh sửa của nhóm lên trang học tập.</p><a class="button" href="#gioi-thieu">Về giới thiệu dự án</a>`};
const escape=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
// Route rendering keeps the six WebQuest sections in a predictable order.
let renderVersion = 0;
async function render() {
  const version = ++renderVersion;
  let id = location.hash.slice(1) || 'gioi-thieu';
  if (!pages[id]) id = 'gioi-thieu';
  const index = menu.findIndex(([key]) => key === id);
  const previous = menu[index - 1];
  const next = menu[index + 1];
  const main = document.getElementById('main');
  main.innerHTML = pages[id]() + `<div class="lesson-nav" aria-label="Chuyển phần học tập">${previous ? `<a class="button alt" href="#${previous[0]}">Trước: ${previous[1]}</a>` : '<span></span>'}${next ? `<a class="button" href="#${next[0]}">Tiếp: ${next[1]}</a>` : ''}</div>`;
  document.getElementById('page-label').textContent = `${String(index+1).padStart(2,'0')} / ${menu[index][1]}`;
  document.title = `${menu[index][1]} · Kết nối câu lạc bộ`;
  document.getElementById('nav').innerHTML = menu.map(([key,title]) => `<a href="#${key}" class="${key===id?'active':''}" ${key===id?'aria-current="page"':''}>${title}</a>`).join('');
  closeMenu();
  window.scrollTo(0,0);
  if (version > 1) main.focus({preventScroll:true});
  // Render rubrics only for the active page; never overwrite a newer route.
  if (id === 'danh-gia') {
    try {
      let data = config.rubricData;
      if (!data) {
        const response = await fetch('rubrics.json');
        if (!response.ok) throw new Error('Rubric unavailable');
        data = await response.json();
      }
      if (renderVersion !== version) return;
      document.getElementById('rubrics').innerHTML = data.map((rows,i) => `<section class="rubric"><h2>Rubric ${i+1} · ${i===0?'Sản phẩm website (nhóm)':'Quá trình và kĩ năng (cá nhân)'}</h2><p class="scroll-hint">Có thể cuộn ngang để xem đầy đủ các mức đánh giá.</p><div class="table-wrap" tabindex="0" role="region" aria-label="Rubric ${i+1}"><table>${rows.map((row,j)=>'<tr>'+row.map((cell,k)=>j===0 ? `<th scope="col">${escape(cell)}</th>` : k===0 ? `<th scope="row">${escape(cell)}</th>` : `<td>${escape(cell)}</td>`).join('')+'</tr>').join('')}</table></div></section>`).join('');
    } catch {
      if (renderVersion === version) document.getElementById('rubrics').innerHTML='<p role="alert">Không tải được bảng tiêu chí. Kiểm tra kết nối rồi tải lại trang.</p>';
    }
  }
}
function closeMenu() {
  document.getElementById('nav').classList.remove('open');
  document.getElementById('toggle').setAttribute('aria-expanded','false');
}
document.getElementById('toggle').onclick = () => {
  const nav = document.getElementById('nav');
  nav.classList.toggle('open');
  document.getElementById('toggle').setAttribute('aria-expanded',String(nav.classList.contains('open')));
};
document.addEventListener('keydown',event => {
  if (event.key === 'Escape' && document.getElementById('nav').classList.contains('open')) {
    closeMenu(); document.getElementById('toggle').focus();
  }
});
window.addEventListener('hashchange',render);
render();
